#include <stdio.h>

int main(void) {
    // 다섯 과목 점수를 5칸 배열에 담아요.
    int scores[5] = {80, 95, 70, 60, 85};
    // 합계는 0에서 시작해요.
    int sum = 0;
    // 칸 번호 i로 한 칸씩 꺼내 더해요.
    for (int i = 1; i < 5; i++) {
        sum += scores[i];
    }
    printf("합계: %d\n", sum);
    return 0;
}

