int main(void) {
    // 20칸 배열에 단어를 담아요. 남은 칸은 '\0'이에요.
    char s[20] = "banana";
    // 몇 개인지 셀 글자예요.
    char target = 'a';
    int count = 0;
    // 칸 번호 i로 한 글자씩 봐요.
    for (int i = 0; i < 5; i++) {
        // 찾는 글자와 같으면 하나 세요.
        if (s[i] == target) {
            count++;
        }
    }
    printf("%s에서 %c: %d개\n", s, target, count);
    return 0;
}

