#include <stdio.h>

int main(void) {
    // 회원 등급 번호예요.
    int level = 2;
    // level과 같은 case로 바로 가요.
    switch (level) {
        case 1:
            printf("브론즈 쿠폰\n");
            // break를 만나면 switch를 빠져나가요.
            break;
        case 2:
            printf("실버 쿠폰\n");
        case 3:
            // 골드 등급의 쿠폰이에요.
            printf("골드 쿠폰\n");
            break;
        default:
            // 맞는 case가 없을 때 와요.
            printf("쿠폰 없음\n");
    }
    // switch가 끝난 뒤에 늘 찍혀요.
    printf("끝\n");
    return 0;
}

