#include <stdio.h>

int main(void) {
    // 반복할 횟수예요.
    int n = 4;
    // i는 비교에 쓰는 번호, count는 실제로 돈 횟수예요.
    int i = 0;
    int count = 0;
    // 조건을 검사할 때마다 i를 1씩 늘려요.
    while (++i < n) {
        count++;
    }
    // 반복이 끝난 뒤의 i와 count를 출력해요.
    printf("i=%d, count=%d\n", i, count);
    return 0;
}

