#include <stdio.h>

int main(void) {
    // 뒤집을 배열이에요.
    int arr[] = {1, 2, 3, 4, 5};
    // 칸 수를 sizeof로 세요.
    int n = sizeof(arr) / sizeof(arr[0]);
    // i번 칸과 짝 칸을 맞바꿔요.
    for (int i = 0; i < n; i++) {
        // 한쪽 값을 temp에 먼저 담아 둬요.
        int temp = arr[i];
        arr[i] = arr[n - 1 - i];
        arr[n - 1 - i] = temp;
    }
    // 칸을 앞에서부터 대괄호에 넣어 출력해요.
    for (int k = 0; k < n; k++) {
        printf("[%d]", arr[k]);
    }
    // 마지막에 줄을 바꿔요.
    printf("\n");
    return 0;
}

