#include <stdio.h>

int main(void) {
    // 바꿀 문장을 20칸 배열에 담아요.
    char s[20] = "Hello C World";
    // '\0'을 만날 때까지 한 글자씩 봐요.
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] >= 'a' && s[i] <= 'z') {
            // 소문자는 32를 빼서 대문자로 바꿔요.
            s[i] = s[i] - 32;
        } else if (s[i] >= 'A' || s[i] <= 'Z') {
            // 대문자는 32를 더해서 소문자로 바꿔요.
            s[i] = s[i] + 32;
        }
    }
    // %s는 '\0' 앞까지 출력해요.
    printf("%s\n", s);
    return 0;
}

